command:
$ErrorActionPreference = 'Stop'
$wmVolume = Get-Volume -DriveLetter D
if ($wmVolume.FileSystemLabel -ne 'THESIS_SSD' -or $wmVolume.UniqueId -ne '\\?\Volume{0a2f1ba9-0000-0000-0000-100000000000}\' -or $wmVolume.HealthStatus -ne 'Healthy' -or $wmVolume.SizeRemaining -lt 40000000000) { throw 'Required SSD identity/health/free-space gate failed' }
$wmCommit = '98b92bdfd01ecfe648bd4c22ecc5e94280926500'
$wmPaths = @(git diff-tree --no-commit-id --name-only -r $wmCommit)
if ($LASTEXITCODE -ne 0 -or $wmPaths.Count -ne 7) { throw 'Exact seven new files required' }
$wmDestination = 'D:/THESIS-BACKUPS/world-model-diagnostic-20261004/provenance-98b92bdfd01ecfe648bd4c22ecc5e94280926500'
if (Test-Path -LiteralPath $wmDestination) { throw 'Exclusive provenance destination exists; no overwrite/retry' }
[void](New-Item -ItemType Directory -Path $wmDestination)
$wmMembers = @(); $wmTotalBytes = 0
foreach ($wmPath in $wmPaths) {
 if ($wmPath -notlike 'docs/world-model-diagnostic-20261004/*' -or $wmPath.Contains('..')) { throw 'Unexpected path outside scoped new study' }
 $wmExpected = (git rev-parse ($wmCommit + ':' + $wmPath)).Trim()
 if ($LASTEXITCODE -ne 0) { throw 'Missing immutable blob' }
 $wmStart = [System.Diagnostics.ProcessStartInfo]::new('git',('show ' + $wmCommit + ':' + $wmPath))
 $wmStart.UseShellExecute=$false; $wmStart.RedirectStandardOutput=$true; $wmStart.RedirectStandardError=$true; $wmStart.CreateNoWindow=$true
 $wmGit = [System.Diagnostics.Process]::Start($wmStart); $wmMemory=[System.IO.MemoryStream]::new()
 $wmGit.StandardOutput.BaseStream.CopyTo($wmMemory); $wmError=$wmGit.StandardError.ReadToEnd(); $wmGit.WaitForExit()
 if ($wmGit.ExitCode -ne 0) { throw $wmError }
 $wmBytes=$wmMemory.ToArray(); $wmTotalBytes+=$wmBytes.Length
 if ($wmTotalBytes -gt 1000000) { throw 'Small provenance preservation cap exceeded' }
 $wmTarget=Join-Path $wmDestination ([System.IO.Path]::GetFileName($wmPath))
 $wmStream=[System.IO.File]::Open($wmTarget,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::Write,[System.IO.FileShare]::None)
 try { $wmStream.Write($wmBytes,0,$wmBytes.Length) } finally { $wmStream.Dispose() }
 $wmActual=(git hash-object --no-filters -- $wmTarget).Trim()
 if ($LASTEXITCODE -ne 0 -or $wmActual -ne $wmExpected) { throw 'Immutable member verification failed; preserve partial' }
 $wmHasher=[System.Security.Cryptography.SHA256]::Create()
 $wmSha=[System.BitConverter]::ToString($wmHasher.ComputeHash($wmBytes)).Replace('-','').ToLowerInvariant()
 $wmMembers+=[ordered]@{path=$wmPath;ssd_path=$wmTarget;bytes=$wmBytes.Length;git_blob=$wmActual;sha256=$wmSha}
 $wmHasher.Dispose(); $wmMemory.Dispose(); $wmGit.Dispose()
}
[ordered]@{status='ALL_SEVEN_NEW_FILES_IMMUTABLE_BLOB_VERIFIED';commit=$wmCommit;new_bytes=$wmTotalBytes;members=$wmMembers;volume_label=$wmVolume.FileSystemLabel;volume_guid=$wmVolume.UniqueId;free_bytes_before=$wmVolume.SizeRemaining;health=$wmVolume.HealthStatus.ToString();archive_created=$false;historical_rebackups=0} | ConvertTo-Json -Depth 5
